func TestEchoRoundTrip(t *testing.T) {
    t.Parallel()

    // Beacon + registry; cleaned up automatically when the test ends
    env := NewTestEnv(t)
    a := env.AddDaemon()
    b := env.AddDaemon()

    // Open a connection from A to B's built-in echo service (port 7)
    conn, err := a.Driver.DialAddr(b.Daemon.Addr(), protocol.PortEcho)
    if err != nil {
        t.Fatalf("dial echo: %v", err)
    }
    defer conn.Close()

    // Send data and verify the echo
    conn.Write([]byte("hello"))
    buf := make([]byte, 5)
    if _, err := io.ReadFull(conn, buf); err != nil {
        t.Fatalf("read: %v", err)
    }
    if string(buf) != "hello" {
        t.Fatalf("echo = %q, want hello", buf)
    }
}

package latency

import (
    "context"
    "encoding/json"
    "fmt"
    "io"
    "time"

    "github.com/pilot-protocol/common/coreapi"
)

// PortLatency is the port the latency service listens on.
const PortLatency uint16 = 1004

// Response is the JSON payload returned to the caller.
type Response struct {
    ReceivedAt time.Time     `json:"received_at"`
    Latency    time.Duration `json:"latency_ns"`
}

// Service is the daemon plugin.
type Service struct{ ln coreapi.Listener }

func (s *Service) Name() string { return "latency" }
func (s *Service) Order() int   { return 200 }

// Start is called by the plugin runtime with the daemon's capabilities.
func (s *Service) Start(ctx context.Context, deps coreapi.Deps) error {
    ln, err := deps.Streams.Listen(PortLatency)
    if err != nil {
        return fmt.Errorf("latency: listen on port %d: %w", PortLatency, err)
    }
    s.ln = ln
    go func() {
        for {
            st, err := ln.Accept()
            if err != nil {
                return
            }
            go handle(st)
        }
    }()
    return nil
}

func (s *Service) Stop(ctx context.Context) error {
    if s.ln == nil {
        return nil
    }
    return s.ln.Close()
}

// handle answers each timestamp the peer sends with the measured latency.
func handle(conn io.ReadWriteCloser) {
    defer conn.Close()
    buf := make([]byte, 1024)
    for {
        n, err := conn.Read(buf)
        if err != nil {
            return
        }
        received := time.Now()

        // Parse the timestamp sent by the caller
        var sent time.Time
        if err := json.Unmarshal(buf[:n], &sent); err != nil {
            return
        }

        // Respond with latency measurement
        resp := Response{
            ReceivedAt: received,
            Latency:    received.Sub(sent),
        }
        data, _ := json.Marshal(resp)
        if _, err := conn.Write(data); err != nil {
            return
        }
    }
}

